// This temporary measurement block records accepted physical demand misses,
// after translation and before the I/D memory engines. Separate memories
// preserve simultaneous I- and D-side events and map to one RAMB18 each.
if (cache_miss_trace_p) begin : gen_cache_miss_trace
  bp_fe_icache_req_s icache_req_cast;
  bp_be_dcache_req_s dcache_req_cast;
  assign icache_req_cast = icache_req_o;
  assign dcache_req_cast = dcache_req_o;

  logic armed_r, icache_overflow_r, dcache_overflow_r;
  logic [8:0] icache_count_r, dcache_count_r;
  logic [31:0] cycle_r;
  (* ram_style = "block" *) logic [63:0] icache_trace_mem [0:255];
  (* ram_style = "block" *) logic [63:0] dcache_trace_mem [0:255];
  logic [63:0] icache_trace_data_r, dcache_trace_data_r;
  logic miss_trace_read_source_r;

  wire icache_miss_accept = armed_r & icache_req_v_o & icache_req_yumi_i
                            & (icache_req_cast.msg_type == e_miss_load);
  wire dcache_miss_accept = armed_r & dcache_req_v_o & dcache_req_yumi_i
                            & (dcache_req_cast.msg_type == e_miss_load);

  assign miss_trace_status_li =
    {{(dword_width_gp-21){1'b0}}, armed_r, dcache_overflow_r, icache_overflow_r
     ,dcache_count_r, icache_count_r};
  assign miss_trace_data_li = miss_trace_read_source_r
                              ? dcache_trace_data_r
                              : icache_trace_data_r;

  always_ff @(posedge clk_i)
    if (reset_i) begin
      armed_r <= 1'b0;
      icache_overflow_r <= 1'b0;
      dcache_overflow_r <= 1'b0;
      icache_count_r <= '0;
      dcache_count_r <= '0;
      cycle_r <= '0;
      miss_trace_read_source_r <= 1'b0;
    end else begin
      cycle_r <= cycle_r + 1'b1;

      if (miss_trace_ctrl_v_lo)
        armed_r <= miss_trace_arm_lo;

      if (miss_trace_clear_lo) begin
        icache_overflow_r <= 1'b0;
        dcache_overflow_r <= 1'b0;
        icache_count_r <= '0;
        dcache_count_r <= '0;
      end else begin
        if (icache_miss_accept) begin
          if (icache_count_r < 9'd256) begin
            icache_trace_mem[icache_count_r[7:0]]
              <= {cycle_r, icache_req_cast.msg_type, icache_req_cast.addr[33:6]};
            icache_count_r <= icache_count_r + 1'b1;
          end else
            icache_overflow_r <= 1'b1;
        end

        if (dcache_miss_accept) begin
          if (dcache_count_r < 9'd256) begin
            dcache_trace_mem[dcache_count_r[7:0]]
              <= {cycle_r, dcache_req_cast.msg_type, dcache_req_cast.addr[33:6]};
            dcache_count_r <= dcache_count_r + 1'b1;
          end else
            dcache_overflow_r <= 1'b1;
        end
      end

      if (miss_trace_read_v_lo) begin
        // Keep the two registered read ports structurally independent so
        // Vivado can infer one simple dual-port block RAM per history.
        icache_trace_data_r <= icache_trace_mem[miss_trace_read_index_lo];
        dcache_trace_data_r <= dcache_trace_mem[miss_trace_read_index_lo];
        miss_trace_read_source_r <= miss_trace_read_source_lo;
      end
    end
end else begin : gen_no_cache_miss_trace
  assign miss_trace_status_li = '0;
  assign miss_trace_data_li = '0;
end

wire is_debug_mode = debug_mode_r;
// Debug Mode grants pseudo M-mode permission
wire is_m_mode = is_debug_mode | (priv_mode_r == `PRIV_MODE_M);
wire is_s_mode = (priv_mode_r == `PRIV_MODE_S);
wire is_u_mode = (priv_mode_r == `PRIV_MODE_U);
wire legacy_context_access_li = legacy_context_user_enable_i | is_m_mode;

`declare_csr(dcsr);

12'h805:  // Accepted cache-miss trace control/status
  csr_data_lo = legacy_context_access_li ? miss_trace_status_i : '0;
12'h806:  // Trace read selector - write-only, reads as 0
  csr_data_lo = '0;
12'h807:  // Selected trace record
  csr_data_lo = legacy_context_access_li ? miss_trace_data_i : '0;
12'h808:  // Protected call capability operand / status

// A control write sets the desired armed state directly. Bit 1 also clears
// counts and overflow flags. A selector write initiates the recorder's
// synchronous BRAM read; bit 8 chooses D (1) or I (0), bits 7:0 select entry.
assign miss_trace_ctrl_v_o = csr_w_v_li & (csr_addr_li == 12'h805)
                             & legacy_context_access_li;
assign miss_trace_arm_o = csr_data_li[0];
assign miss_trace_clear_o = miss_trace_ctrl_v_o & csr_data_li[1];
assign miss_trace_read_v_o = csr_w_v_li & (csr_addr_li == 12'h806)
                             & legacy_context_access_li;
assign miss_trace_read_source_o = csr_data_li[8];
assign miss_trace_read_index_o = csr_data_li[7:0];

# Environment entries are not Verilog defines. Apply only the experiment's
# explicit allowlist to BOTH the source IP and the final integrating project.
# The latter matters for a BD packaged with imported HDL and no synthesis DCP.
proc vivado_experiment_defines {} {
    set names {BP_RETAINED_BUFFER BP_RETAINED_I_LINES BP_RETAINED_D_LINES BP_RETAINED_SETS}
    set present 0
    foreach name $names { if {[info exists ::env($name)]} { incr present } }
    if {$present != 0 && $present != [llength $names]} {
        error "incomplete retained-buffer Verilog configuration"
    }
    set result [list]
    foreach name [concat $names {BP_RETAINED_OBSERVE BP_AXI_RESPONSE_DELAY}] {
        if {![info exists ::env($name)]} { continue }
        set value $::env($name)
        if {![regexp {^(0|[1-9][0-9]*)$} $value]} {
            error "$name must be a canonical nonnegative integer, got '$value'"
        }
        if {$name in {BP_RETAINED_BUFFER BP_RETAINED_OBSERVE} && $value > 1} {
            error "$name must be 0 or 1"
        }
        if {$name eq "BP_AXI_RESPONSE_DELAY" && $value > 384} {
            error "$name must be in 0..384"
        }
        if {$name in {BP_RETAINED_I_LINES BP_RETAINED_D_LINES} && $value > 65535} {
            error "$name exceeds the 16-bit reported line count"
        }
        if {$name eq "BP_RETAINED_SETS" && ($value < 1 || $value > 32768 || ($value & ($value-1)) != 0)} {
            error "$name must be a power of two in 1..32768"
        }
        lappend result "$name=$value"
    }
    return $result
}

proc vivado_apply_experiment_defines {} {
    set requested [vivado_experiment_defines]
